arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d.get('error')); sys.exit()
for c in d.get('channels',[]):
    if c.get('name')=='support' or 'support' in c.get('name',''):
        print(c['id'], c['name'], c.get('is_archived'))
"

